import React from 'react'
import { TouchableOpacity, Image } from 'react-native'
import { Icon, Text, View } from 'native-base'

import AsyncStorage from '@react-native-community/async-storage'
import styles from '../styles'

import theme from '@theme/styles'
import { navigate } from '@utility/navigation'
import { __ } from '@utility/translation'
import Thumbnail from "./Thumbnail"
import {REACT_APP_REQ} from '@env'

export default class extends React.Component {
  constructor(props) {
    super(props)
    this.state={
      bienes:[],
    }
  }

  componentDidMount() {
      fetch(REACT_APP_REQ+'/property/seo', {
         method: 'GET',
         headers: {'Content-Type': 'application/json'}
      })
      .then((response) => response.json())
      .then((responseJson) => {
         this.setState({
            bienes: responseJson.data,
         })
         
      })
      .catch((error) => {
         console.error(error);
      });
  }

  _storeData = async (idb) => {
    try {
      await AsyncStorage.setItem(
        'bien',
        idb.toString()
      );
    } catch (error) {
      // Error saving data
    }
  };

  render () {
    const {bienes} = this.state;
    return (
      <>
      {bienes.map((bien, i) => (
        <TouchableOpacity
          style={styles.sponsoredItem}
          onPress={async () => {
            let idb = bien.id_bien;
            await this._storeData(idb);
            navigate('PublicPropertyDetail')
          }}>
          <View>
            <Thumbnail img={bien.id_bien}/>
          </View>
          <View style={styles.sponsoredContent2}>
            <View style={theme.row}>
              <Text style={styles.sponsoredPrice}>$ {bien.precio}</Text>
            </View>
            <View style={theme.row}>
              <Text style={styles.sponsoredLocation}>{bien.direccion}</Text>
            </View>
          </View>
          <View style={styles.sponsoredContent3}>
            <View style={styles.sponsoredCol}>
              <Icon name='bed' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{bien.habitaciones}</Text>
            </View>
            <View style={styles.sponsoredCol}>
              <Icon name='bathtub' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{bien.bathrooms}</Text>
            </View>
            <View style={styles.sponsoredCol}>
              <Icon name='expand' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{bien.dimensiones} m²</Text>
            </View>
          </View>
        </TouchableOpacity>
        ))}
      </>
    
    )
  }
}
