import React from 'react'
import { FlatList, TouchableOpacity } from 'react-native'
import { View, Icon, Text } from 'native-base'
import { navigate } from '@utility/navigation'

import styles from '../styles'
import Item from './Item'
import Placeholder from './Placeholder'

import theme from '@theme/styles'
import { __ } from '@utility/translation'

export default class extends React.Component {
  constructor(props) {
    super(props)

    this.renderTemplate = this.renderTemplate.bind(this)
    this.renderItem = this.renderItem.bind(this)
  }

  renderTemplate() {
    return <Placeholder />
  }

  renderItem({ item }) {
    return (
      <Item
        language={this.props.language}
        item={item}
      />
    )
  }

  render() {
    return (
      <>
        <View style={styles.sponsoredContainer}>
          <View style={styles.sponsoredHeader}>
            <View style={styles.sponsoredCol}>
              <Icon name='map-marker-multiple' type='MaterialCommunityIcons' style={[theme.grey, theme.huge]} />
              <Text style={styles.sponsoredTitle}>{__('Top Vehículos')}</Text>
            </View>
          </View>
          <View style={styles.sponsoredContent}>
            <FlatList
              data={this.props.fetching ? [1, 2] : this.props.list}
              vertical
              showsHorizontalScrollIndicator={false}
              renderItem={this.props.fetching ? this.renderTemplate : this.renderItem}
            />
          </View>
        </View>
      </>
    )
  }
}
