import React from 'react'
import { TouchableOpacity, Image } from 'react-native'
import { Icon, Text, View } from 'native-base'

import styles from '../styles'

import theme from '@theme/styles'
import { navigate } from '@utility/navigation'
import { __ } from '@utility/translation'

export default class extends React.Component {
  render () {
    const item = this.props.item

    return (
      <>
        <TouchableOpacity
          style={styles.sponsoredItem}
          onPress={() => {
            navigate('PublicPropertyDetail')
          }}
        >
          <View>
            <Image source={{ uri: item.image }} style={styles.sponsoredImg} resizeMode='cover' />
          </View>
          <View style={styles.sponsoredContent2}>
            <View style={theme.row}>
              <Text style={styles.sponsoredPrice}>{item.price}</Text>
            </View>
            <View style={theme.row}>
              <Text style={styles.sponsoredLocation}>{item['location_' + this.props.language] || item.location}</Text>
            </View>
          </View>
          <View style={styles.sponsoredContent3}>
            <View style={styles.sponsoredCol}>
              <Icon name='bed' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{item.bedroom}</Text>
            </View>
            <View style={styles.sponsoredCol}>
              <Icon name='bathtub' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{item.bathroom}</Text>
            </View>
            <View style={styles.sponsoredCol}>
              <Icon name='view-grid' type='MaterialCommunityIcons' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{item.area}</Text>
            </View>
          </View>
        </TouchableOpacity>
      </>
    )
  }
}
