import React from 'react'
import { TouchableOpacity, Image } from 'react-native'
import { Icon, Text, View } from 'native-base'
import AsyncStorage from '@react-native-community/async-storage'
import styles from '../styles'
import theme from '@theme/styles'
import { navigate } from '@utility/navigation'
import { __ } from '@utility/translation'
import Thumbnail from "./Thumbnail"
import {REACT_APP_REQ} from '@env'

let dato = "";
const getDato = async() => {
  try{
  const result = await AsyncStorage.getItem('ruta');
  console.log(result);
  dato=result;
}catch(error){
  console.log(error);
}
}
let route="";
export default class extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      dataSource:[],
      url: dato,
    };
  }
  _storeData = async (idb) => {
    try {
      await AsyncStorage.setItem(
        'bien',
        idb.toString()
      );
    } catch (error) {
      // Error saving data
    }
  };
  

 async componentDidMount() {
    let token =  AsyncStorage.getItem('token');
    await getDato();
    fetch(dato, {
           method: 'GET',
           headers: {'Content-Type': 'application/json', 'api-token' : token},
           'credentials' :'include',
           
        })
        .then((response) => response.json())
        .then((responseJson) => {
           this.setState({
              dataSource: responseJson.data,
              
           })
          
        })
        .catch((error) => {
           console.error(error);
        });
       
  
     }
  render() {
    const item = this.props.item;
    const {dataSource}=this.state;
    console.log(dataSource);
   
    return (
      <>
       {dataSource.map((dataSource, i) => (
        <TouchableOpacity style={styles.propertyContainer} underlayColor='transparent' onPress={async () => {
          let idb = dataSource.id_bien;
          await this._storeData(idb);
          navigate('PublicPropertyDetail') }}>
          <View>
            <Thumbnail img={dataSource.id_bien}/>
          </View>
            <View style={theme.row}>
              <View>
                <Text style={styles.propertyPrice}>$ {dataSource.precio}</Text>
                <Text style={styles.propertyLocation}>{dataSource.direccion}</Text>
              </View>
            </View>
            <View style={styles.propertyContent}>
              <View style={styles.propertyOverview}>
                <Icon name='bed' type='FontAwesome' style={styles.propertyIcon} />
                <Text style={styles.propertyNo}>{dataSource.habitaciones}</Text>
              </View>
              <View style={styles.propertyOverview}>
                <Icon name='bathtub' type='FontAwesome' style={styles.propertyIcon} />
                <Text style={styles.propertyNo}>{dataSource.bathrooms}</Text>
              </View>
              <View style={styles.propertyOverview}>
                <Icon name='expand' type='FontAwesome' style={styles.propertyIcon} />
                <Text style={styles.propertyNo}>{dataSource.dimensiones} m²</Text>
              </View>
            </View>
        </TouchableOpacity>
         ))}
      </>
    )
  }
}
