import React from 'react'
import { TouchableOpacity, Image } from 'react-native'
import { Icon, Text, View } from 'native-base'

import styles from '../styles'

import theme from '@theme/styles'
import { navigate } from '@utility/navigation'
import { __ } from '@utility/translation'

export default class extends React.Component {
  render() {
    const item = this.props.item

    return (
      <>
        <TouchableOpacity underlayColor='transparent' onPress={() => { navigate('PublicPropertyDetail') }}>
          <View style={styles.favoriteContainer}>
            <Image source={{ uri: item.image }} style={styles.favoriteImg} />
            <View style={styles.favoriteInfo}>
              <View style={theme.row}>
                <View>
                <Text style={styles.favoritePrice}>{item.price}</Text>
                <Text style={styles.favoriteLocation}>{item.location}</Text>
                </View>
              </View>
              <View style={styles.favoriteContent}>
                <View style={styles.favoriteOverview}>
                  <Icon name='bed' type='FontAwesome' style={styles.favoriteIcon} />
                  <Text style={styles.favoriteNo}>{item.bedroom}</Text>
                </View>
                <View style={styles.favoriteOverview}>
                  <Icon name='bathtub' type='FontAwesome' style={styles.favoriteIcon} />
                  <Text style={styles.favoriteNo}>{item.bathroom}</Text>
                </View>
              </View>
            </View>
            <TouchableOpacity style={styles.trash} onPress={this.props.onDelete}>
              <Icon name='trash-o' type='FontAwesome' style={styles.favoriteIcon} />
            </TouchableOpacity>
          </View>
        </TouchableOpacity>
      </>
    )
  }
}
