import React from 'react'
import { TouchableOpacity, Image } from 'react-native'
import { Icon, Text, View } from 'native-base'

import styles from '../styles'

import theme from '@theme/styles'
import { navigate } from '@utility/navigation'
import { __ } from '@utility/translation'
import AsyncStorage from '@react-native-community/async-storage'

export default class extends React.Component {
  render() {
    const item = this.props.item

    return (
      <>
        <TouchableOpacity style={styles.propertyContainer} underlayColor='transparent' onPress={() => { AsyncStorage.setItem('bien', item.id_bien), navigate('MemberPropertyAdd') }}>
          <View>
            <Image source={{ uri: item.image }} style={styles.propertyImg} />
            <View style={styles.propertyImgBg} />
            <Icon name='check-circle' type='MaterialIcons' style={styles.propertyFavorite} />
          </View>
          <View style={styles.propertyContent}>
            <View style={styles.propertyOverview}>
              <View>
                <Text style={styles.propertyPrice}>{item.price}</Text>
                <Text style={styles.propertyLocation}>{item.location}</Text>
              </View>
            </View>
            <View style={styles.propertyOverview}>
              <Icon name='bed' type='FontAwesome' style={styles.propertyIcon} />
              <Text style={styles.propertyNo}>{item.bedroom}</Text>
            </View>
            <View style={styles.propertyOverview}>
              <Icon name='bathtub' type='FontAwesome' style={styles.propertyIcon} />
              <Text style={styles.propertyNo}>{item.bathroom}</Text>
            </View>
          </View>
          <View style={styles.propertyRowIcon}>
            <View style={styles.propertyLeft}>
              <TouchableOpacity style={styles.propertyBtn}>
                <Icon name='edit' type='FontAwesome' style={styles.propertyLeftIcon} />
                <Text style={styles.propertyText}>{__('Editar')}</Text>
              </TouchableOpacity>
              <TouchableOpacity style={styles.propertyBtn} onPress={this.props.onDelete}>
                <Icon name='trash' type='FontAwesome' style={styles.propertyLeftIcon} />
                <Text style={styles.propertyText}>{__('Eliminar')}</Text>
              </TouchableOpacity>
            </View>
            <View style={styles.propertyRight}>
              <Text style={styles.propertyDate}>{__('Inscrita el')}:{'\n'} 15 Ago 2018</Text>
            </View>
          </View>
        </TouchableOpacity>
      </>
    )
  }
}
