import React from 'react'
import { TouchableOpacity, Image } from 'react-native'
import { Icon, Text, View } from 'native-base'

import AsyncStorage from '@react-native-community/async-storage'
import styles from '../styles'

import theme from '@theme/styles'
import { navigate } from '@utility/navigation'
import { __ } from '@utility/translation'
import Thumbnail from "./Thumbnail"
import {REACT_APP_REQ} from '@env'

export default class extends React.Component {
  constructor(props) {
    super(props)
    this.state={
      vehiculos:[],
    }
  }

  componentDidMount() {
      fetch(REACT_APP_REQ+'/vehicle/seo', {
         method: 'GET',
         headers: {'Content-Type': 'application/json'}
      })
      .then((response) => response.json())
      .then((responseJson) => {
         this.setState({
            vehiculos: responseJson.data,
         })
         
      })
      .catch((error) => {
         console.error(error);
      });
  }

  _storeData = async (idb) => {
    try {
      await AsyncStorage.setItem(
        'vehiculo',
        idb.toString()
      );
    } catch (error) {
      // Error saving data
    }
  };

  render () {
    const {vehiculos} = this.state;
    return (
      <>
      {vehiculos.map((vehiculo, i) => (
        <TouchableOpacity
          style={styles.sponsoredItem}
          onPress={async () => {
            let idb = vehiculo.id_vehiculo;
            await this._storeData(idb);
            navigate('PublicVehicleDetail')
          }}>
          <View>
            <Thumbnail img={vehiculo.id_vehiculo}/>
          </View>
          <View style={styles.sponsoredContent2}>
            <View style={theme.row}>
              <Text style={styles.sponsoredPrice}>$ {vehiculo.precio}</Text>
            </View>
            <View style={theme.row}>
              <Text style={styles.sponsoredLocation}>{vehiculo.marca} {vehiculo.modelo} {vehiculo.year}</Text>
            </View>
          </View>
          <View style={styles.sponsoredContent3}>
            <View style={styles.sponsoredCol}>
              <Icon name='car' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{vehiculo.cabina}</Text>
            </View>
            <View style={styles.sponsoredCol}>
              <Icon name='gas-pump' type='FontAwesome5' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{vehiculo.combustible}</Text>
            </View>
            <View style={styles.sponsoredCol}>
              <Icon name='tachometer' type='FontAwesome' style={styles.sponsoredIcon} />
              <Text style={styles.sponsoredValue}>{vehiculo.kilometraje} km</Text>
            </View>
          </View>
        </TouchableOpacity>
        ))}
      </>
    
    )
  }
}
